@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@(Category is not null ? FormatCategory(Category) : "All Recipes")</h1>

@if (Category is null)
{
    <ul>
        <li><a href="recipes/appetizers">Appetizers</a></li>
        <li><a href="recipes/main-courses">Main Courses</a></li>
        <li><a href="recipes/desserts">Desserts</a></li>
    </ul>
}
else
{
    <div class="row">
        @foreach (var recipe in GetRecipes(Category))
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Summary</p>
                        <a href="recipes/@Category/@recipe.Slug" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string FormatCategory(string category) => category.Replace("-", " ").ToUpperInvariant() switch
    {
        var s when s.Length > 0 => char.ToUpper(category[0]) + category[1..].Replace("-", " "),
        _ => category
    };

    private List<RecipeSummary> GetRecipes(string category) => category switch
    {
        "appetizers" => new()
        {
            new("Bruschetta", "bruschetta", "Classic Italian toasted bread with tomatoes and basil."),
            new("Stuffed Mushrooms", "stuffed-mushrooms", "Savory mushrooms filled with cream cheese and herbs."),
        },
        "main-courses" => new()
        {
            new("Spaghetti Carbonara", "spaghetti-carbonara", "Creamy Roman pasta with pancetta and egg."),
            new("Grilled Salmon", "grilled-salmon", "Fresh salmon fillet with lemon and dill."),
        },
        "desserts" => new()
        {
            new("Chocolate Lava Cake", "chocolate-lava-cake", "Rich chocolate cake with a molten center."),
            new("Tiramisu", "tiramisu", "Classic Italian coffee-flavored layered dessert."),
        },
        _ => new()
    };

    private record RecipeSummary(string Title, string Slug, string Summary);
}

@page "/recipes/{Category}/{Slug}"

<PageTitle>@GetRecipe()?.Title - RecipeShare</PageTitle>

@if (GetRecipe() is { } recipe)
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @FormatCategory(Category!)</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h3>Rate this Recipe</h3>
    <StarRating RecipeSlug="@Slug" />
}
else
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="recipes">Back to all recipes</a>
}

@code {
    [Parameter] public string? Category { get; set; }
    [Parameter] public string? Slug { get; set; }

    private string FormatCategory(string category) =>
        char.ToUpper(category[0]) + category[1..].Replace("-", " ");

    private RecipeData? GetRecipe() => (Category, Slug) switch
    {
        ("appetizers", "bruschetta") => new("Bruschetta",
            new[] { "4 slices crusty bread", "2 ripe tomatoes, diced", "Fresh basil leaves", "2 cloves garlic", "Extra virgin olive oil", "Salt and pepper" },
            new[] { "Toast bread slices until golden.", "Rub each slice with a cut garlic clove.", "Mix diced tomatoes with olive oil, salt, and torn basil.", "Spoon tomato mixture onto toast and serve immediately." }),
        ("appetizers", "stuffed-mushrooms") => new("Stuffed Mushrooms",
            new[] { "12 large button mushrooms", "200g cream cheese", "2 cloves garlic, minced", "Fresh parsley", "Parmesan cheese", "Olive oil" },
            new[] { "Preheat oven to 190°C (375°F).", "Remove stems from mushrooms and finely chop stems.", "Mix cream cheese, chopped stems, garlic, and parsley.", "Fill mushroom caps with the mixture.", "Top with Parmesan and bake for 20 minutes." }),
        ("main-courses", "spaghetti-carbonara") => new("Spaghetti Carbonara",
            new[] { "400g spaghetti", "200g pancetta or guanciale", "4 egg yolks", "100g Pecorino Romano, grated", "Black pepper" },
            new[] { "Cook spaghetti in salted boiling water until al dente.", "Crisp pancetta in a pan until golden.", "Whisk egg yolks with grated Pecorino and pepper.", "Drain pasta, reserving some water. Toss with pancetta.", "Remove from heat, stir in egg mixture. Add pasta water to loosen." }),
        ("main-courses", "grilled-salmon") => new("Grilled Salmon",
            new[] { "4 salmon fillets", "2 lemons", "Fresh dill", "Olive oil", "Salt and pepper", "Garlic butter" },
            new[] { "Season salmon with salt, pepper, and olive oil.", "Heat grill to medium-high.", "Grill salmon skin-side down for 4 minutes.", "Flip and cook 3 more minutes until done.", "Serve with lemon wedges and fresh dill." }),
        ("desserts", "chocolate-lava-cake") => new("Chocolate Lava Cake",
            new[] { "200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour", "Butter and cocoa for ramekins" },
            new[] { "Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins and bake 10-12 minutes.", "Center should be slightly jiggly. Invert onto plates." }),
        ("desserts", "tiramisu") => new("Tiramisu",
            new[] { "500g mascarpone cheese", "4 eggs, separated", "100g sugar", "300ml strong espresso, cooled", "Ladyfinger biscuits", "Cocoa powder" },
            new[] { "Beat egg yolks with sugar until pale and creamy.", "Fold in mascarpone until smooth.", "Whip egg whites to stiff peaks and fold into mixture.", "Dip ladyfingers briefly in espresso.", "Layer soaked biscuits and mascarpone in a dish.", "Refrigerate 4+ hours. Dust with cocoa before serving." }),
        _ => null
    };

    private record RecipeData(string Title, string[] Ingredients, string[] Steps);
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public string? RecipeSlug { get; set; }

    private int CurrentRating { get; set; }

    private void Rate(int rating)
    {
        CurrentRating = rating;
    }
}

.star-rating {
    font-size: 1.8rem;
    display: inline-flex;
    align-items: center;
    gap: 0.1rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

